<?php
class RecruitingController {
 private $m;public function __construct(){if(!isStaffAdmin())redirect('login');$this->m=new HrSuite();}
 public function index(){require_capability('recruiting.review');$cid=requireAdminCompany();$selected=(int)($_GET['vacancy_id']??0);$this->view('admin/recruiting/index',['vacancies'=>$this->m->vacancies($cid),'applications'=>$selected?$this->m->applications($selected):[],'selected'=>$selected]);}
 public function saveVacancy(){require_capability('recruiting.publish');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('recruiting/index');csrf_verify();$title=trim($_POST['title']??'');if($title===''){$_SESSION['flash_error']='Indicá el título.';redirect('recruiting/index');}$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$title),'-')).'-'.substr(bin2hex(random_bytes(3)),0,6);$criteria=array_values(array_filter(array_map('trim',preg_split('/\r?\n/',$_POST['criteria']??''))));$pipeline=array_values(array_unique(array_filter(array_map(fn($s)=>preg_replace('/[^a-z0-9_áéíóúñ-]/iu','_',trim($s)),preg_split('/\r?\n/',$_POST['pipeline']??'')))));if(!$pipeline)$pipeline=['received','shortlist','interview','offer','hired','rejected'];$status=($_POST['status']??'draft')==='published'?'published':'draft';$ok=$this->m->execute('INSERT INTO job_vacancies(company_id,branch_id,title,slug,description,requirements_json,pipeline_json,status,published_at,closes_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[adminCompanyId(),(int)($_POST['branch_id']??0)?:null,$title,$slug,trim($_POST['description']??''),json_encode($criteria,JSON_UNESCAPED_UNICODE),json_encode($pipeline,JSON_UNESCAPED_UNICODE),$status,$status==='published'?date('Y-m-d H:i:s'):null,trim($_POST['closes_at']??'')?:null,(int)$_SESSION['user_id']]);if($ok)$this->m->audit()->record('recruiting.vacancy.created','job_vacancy',$this->m->one('SELECT LAST_INSERT_ID() id')->id,null,['title'=>$title,'criteria'=>$criteria,'pipeline'=>$pipeline],'',adminCompanyId());redirect('recruiting/index');}
 public function move($id){require_capability('recruiting.review');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('recruiting/index');csrf_verify();$app=$this->m->one('SELECT ja.*,jv.company_id FROM job_applications ja JOIN job_vacancies jv ON jv.id=ja.vacancy_id WHERE ja.id=?',[(int)$id]);if(!$app||(int)$app->company_id!==adminCompanyId())redirect('recruiting/index');$stage=preg_replace('/[^a-z_]/','',$_POST['stage']??'received');$this->m->execute('UPDATE job_applications SET current_stage=?,status=? WHERE id=?',[$stage,$stage==='hired'?'hired':($stage==='rejected'?'rejected':'active'),$id]);$this->m->execute('INSERT INTO application_events(application_id,event_type,from_stage,to_stage,notes,actor_user_id) VALUES(?,?,?,?,?,?)',[$id,'stage_changed',$app->current_stage,$stage,trim($_POST['notes']??'')?:null,(int)$_SESSION['user_id']]);$this->m->audit()->record('recruiting.stage.changed','job_application',$id,['stage'=>$app->current_stage],['stage'=>$stage],trim($_POST['notes']??''),adminCompanyId());redirect('recruiting/index?vacancy_id='.$app->vacancy_id);}
 public function score($id){require_capability('recruiting.ai');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('recruiting/index');csrf_verify();$app=$this->application($id);if(!$app)redirect('recruiting/index');$path=dirname(APPROOT).'/storage/private/'.$app->cv_path;$text=$this->extractText($path);if(trim($text)===''){$_SESSION['flash_error']='No se pudo extraer texto del CV. Podés continuar con revisión manual.';redirect('recruiting/index?vacancy_id='.$app->vacancy_id);}$svc=new OpenAiCvService();$result=$svc->analyze($text,json_decode($app->requirements_json,true)?:[]);if(!$result['ok']){$_SESSION['flash_error']=$result['message'];}else{$r=$result['result'];$this->m->execute('UPDATE job_applications SET ai_score=?,ai_result_json=?,ai_model=?,ai_criteria_hash=?,ai_scored_at=NOW() WHERE id=?',[$r['score'],json_encode($r,JSON_UNESCAPED_UNICODE),$result['model'],hash('sha256',$app->requirements_json),$id]);$this->m->audit()->record('recruiting.ai.scored','job_application',$id,null,['score'=>$r['score'],'model'=>$result['model'],'criteria_hash'=>hash('sha256',$app->requirements_json)],'Revisión humana obligatoria',adminCompanyId());$_SESSION['flash_success']='Ranking IA actualizado; requiere revisión humana.';}redirect('recruiting/index?vacancy_id='.$app->vacancy_id);}
 public function downloadCv($id){require_capability('recruiting.review');$a=$this->application($id);if(!$a){http_response_code(404);exit;}$abs=dirname(APPROOT).'/storage/private/'.$a->cv_path;if(!is_file($abs)){http_response_code(404);exit;}header('Content-Type: '.(mime_content_type($abs)?:'application/octet-stream'));header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($a->cv_original_name)).'"');header('X-Content-Type-Options: nosniff');readfile($abs);exit;}
 public function onboard($id){require_capability('recruiting.review');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('recruiting/index');csrf_verify();$a=$this->application($id);if(!$a)redirect('recruiting/index');$candidate=$this->m->one('SELECT c.* FROM candidates c JOIN job_applications ja ON ja.candidate_id=c.id WHERE ja.id=?',[(int)$id]);$duplicate=$this->m->one('SELECT id FROM users WHERE email=? LIMIT 1',[$candidate->email]);if($duplicate){$_SESSION['flash_error']='Existe un usuario con ese email. RRHH debe revisar el posible duplicado.';redirect('recruiting/index?vacancy_id='.$a->vacancy_id);}$username='pre'.(int)$candidate->id.'_'.substr(bin2hex(random_bytes(3)),0,6);$password=password_hash(bin2hex(random_bytes(16)),PASSWORD_DEFAULT);$this->m->execute("INSERT INTO users(username,password,full_name,email,phone_number,role,company_id,branch_id,is_active,employment_status) VALUES(?,?,?,?,?,'empleado',?,?,0,'preingreso')",[$username,$password,$candidate->full_name,$candidate->email,$candidate->phone,$a->company_id,$a->branch_id?:null]);$uid=$this->m->one('SELECT LAST_INSERT_ID() id')->id;$this->m->execute("INSERT INTO onboarding_checklists(user_id,company_id,source_application_id,status,created_by) VALUES(?,?,?,'active',?)",[$uid,$a->company_id,$id,(int)$_SESSION['user_id']]);$check=$this->m->one('SELECT LAST_INSERT_ID() id')->id;foreach(['personal_data'=>'Datos personales y domicilio','documents'=>'Documentación y cobertura médica','account'=>'Cuenta y accesos','position'=>'Puesto, área y sucursal','ppe'=>'EPP y talles','assets'=>'Activos asignados','training'=>'Capacitación inicial','policies'=>'Acuse de políticas'] as $key=>$label)$this->m->execute('INSERT INTO onboarding_tasks(checklist_id,task_key,label) VALUES(?,?,?)',[$check,$key,$label]);$this->m->execute("UPDATE job_applications SET status='hired',current_stage='hired' WHERE id=?",[$id]);$this->m->audit()->record('recruiting.onboarding.created','user',$uid,null,['application_id'=>$id,'status'=>'preingreso'],'',adminCompanyId());$_SESSION['flash_success']='Preingreso creado con checklist. La cuenta queda inactiva hasta completar la revisión.';redirect('admin/employeeProfile/'.$uid);}
 private function application($id){$a=$this->m->one('SELECT ja.*,jv.requirements_json,jv.pipeline_json,jv.company_id,jv.branch_id FROM job_applications ja JOIN job_vacancies jv ON jv.id=ja.vacancy_id WHERE ja.id=?',[(int)$id]);return $a&&(int)$a->company_id===adminCompanyId()?$a:null;}
 private function extractText($path){if(strtolower(pathinfo($path,PATHINFO_EXTENSION))==='docx'&&class_exists('ZipArchive')){$z=new ZipArchive();if($z->open($path)===true){$xml=$z->getFromName('word/document.xml');$z->close();return trim(strip_tags(str_replace(['</w:p>','</w:tr>'],["\n","\n"],$xml)));}}$bin=defined('PDFTOTEXT_BIN')?PDFTOTEXT_BIN:'pdftotext';$tmp=tempnam(sys_get_temp_dir(),'cvtxt');$cmd=escapeshellarg($bin).' -layout '.escapeshellarg($path).' '.escapeshellarg($tmp);@exec($cmd,$o,$code);$text=$code===0&&is_file($tmp)?file_get_contents($tmp):'';@unlink($tmp);return $text;}
 private function view($v,$d){require APPROOT.'/views/'.$v.'.php';}
}
